import React, { useEffect, useState } from 'react';

function App() {
  const [data, setData] = useState({
    winner: '',
    numberOfTimesText: '',
    victoryReason: 'What defeats a measly worm?',
    emoji: '🐛',
    color: 'green',
  });

  const [loser, setLoser] = useState("A Measly Worm");
  const [winner, setWinner] = useState("A Mighty Defender");

  useEffect(() => {

    console.log('Data updated:', data);
  }, [data]);

  const [input, setInput] = useState('');

  const handleSend = async () => {
    try {
      const response = await fetch('http://localhost:3000/api/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: input + '|' + loser }),
      });
      const result = await response.json();
      setData(result.result);
      setLoser(result.result.loser);
      setWinner(result.result.winner);
      console.log('Data set:', data);
      setInput('');
    } catch (err) {
      console.error('Error sending message:', err);
    }
  };

  return (
    <div className="container">
      <h1 style={{ color: data.color }}>{loser}</h1>
      <h2>{data.winner || ''}</h2>
      <h4>{data.victoryReason}</h4>
      <h5>{data.emoji}</h5>
      <h3 style={{color:data.color }}>{data.numberOfTimesText}</h3>
      <input
        type="text"
        value={input}
        onChange={e => setInput(e.target.value)}
        placeholder="Type your challenger's name"
      />
      <button onClick={handleSend}>Battle!</button>
    </div>
  );
}

export default App;
